package org.firstinspires.ftc.teamcode.robot.subsystems;

import Ori.Coval.Logging.Logger.KoalaLog;
import com.qualcomm.robotcore.hardware.*;
import org.firstinspires.ftc.teamcode.core.lib.interfaces.Subsystem;
import org.firstinspires.ftc.teamcode.robot.Constants;

/**
 * Subsystem for controlling an intake mechanism to collect game elements. Generated by FGCLib
 * Studio.
 */
public class Intake implements Subsystem {
  private static Intake instance;
  private DcMotor motor1;
  private boolean intakeToggle = false;

  private double intakePower = 0;

  /** Private constructor for singleton pattern */
  protected Intake() {}

  /** Returns the singleton instance of the subsystem */
  public static synchronized Intake getInstance() {
    if (instance == null) {
      instance = new Intake();
    }
    return instance;
  }

  /** Sets manual power to the mechanism motors. */
  public void setPower(double power) {
    motor1.setPower(power);
  }

  public void setIntakePower(double intakePower) {
    this.intakePower = intakePower;
  }

  /** Stops the mechanism movement. */
  public void stopIntake() {
    setIntakePower(0);
  }

  /** Initializes hardware and PID controllers */
  @Override
  public void initialize(HardwareMap hardwareMap) {
    motor1 = hardwareMap.get(DcMotor.class, Constants.Intake.MOTOR_NAME);
    motor1.setDirection(
        Constants.Intake.IS_INVERTED ? DcMotor.Direction.REVERSE : DcMotor.Direction.FORWARD);
    motor1.setMode(DcMotor.RunMode.RUN_WITHOUT_ENCODER);
  }

  /** Main control loop, handled by GamepadManager */
  @Override
  public void execute() {
    KoalaLog.log("intakeToggle", intakeToggle, true);
    KoalaLog.log("intake power", intakePower, true);

    if (intakeToggle) setPower(intakePower);
  }

  /** Reset state when OpMode starts */
  @Override
  public void start() {}

  /** Ensures safety when OpMode stops */
  @Override
  public void stop() {
    stopIntake();
  }

  public void toggleIntake() {
    intakeToggle = !intakeToggle;
  }

  public boolean isIntakeToggle() {
    return intakeToggle;
  }
}
